package com.github.amateurishprogrammer.electronicsknowledge.data
import android.content.Context
import androidx.room.withTransaction
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
class KnowledgeRepository(private val context:Context,private val db:AppDatabase){private val dao=db.dao();private val json=Json{ignoreUnknownKeys=true};fun categories()=dao.categories();fun entries()=dao.entries();fun states()=dao.states();suspend fun ensureContent(){val b=json.decodeFromString<ContentBundle>(context.assets.open("content-bundle.json").bufferedReader().use{it.readText()});if(dao.version()==b.manifest.contentVersion)return;db.withTransaction{dao.clearEntries();dao.clearCategories();dao.putCategories(b.categories.map{CategoryEntity(it.id,it.title,it.sortOrder)});dao.putEntries(b.entries.map{EntryEntity(it.id,it.categoryId,it.title,(listOf(it.title,it.englishName,it.summary)+it.aliases+it.keywords).joinToString(" ").lowercase(),json.encodeToString(it))});dao.putMeta(ContentMetaEntity(version=b.manifest.contentVersion))}}fun decode(e:EntryEntity)=json.decodeFromString<KnowledgeEntry>(e.payload);suspend fun toggle(id:String){val o=dao.state(id)?:EntryStateEntity(id);dao.putState(o.copy(favorite=!o.favorite))};suspend fun viewed(id:String){val o=dao.state(id)?:EntryStateEntity(id);dao.putState(o.copy(lastViewedAt=System.currentTimeMillis()))}}
